<?php
namespace qqworld_collector\module\auto_save_attachments; use qqworld_collector\lib; class local_mark extends lib { var $options; var $image_types = array('image/jpeg', 'image/gif', 'image/png', 'image/webp', 'image/x-ms-bmp'); var $baseurl; var $basedir; var $log_path; public function __construct() { add_action( 'wp_ajax_qqworld-collector-refresh-local-cache', array($this, 'refresh_local_cache') ); add_action( 'wp_ajax_nopriv_qqworld-collector-refresh-local-cache', array($this, 'refresh_local_cache') ); add_action( 'wp_ajax_qqworld-collector-get-local-cache', array($this, 'get_local_cache') ); add_action( 'wp_ajax_nopriv_qqworld-collector-get-local-cache', array($this, 'get_local_cache') ); add_action( 'wp_ajax_qqworld-collector-remove-local-cache', array($this, 'remove_local_cache') ); add_action( 'wp_ajax_nopriv_qqworld-collector-remove-local-cache', array($this, 'remove_local_cache') ); } public function init() { $upload_dir = wp_upload_dir(); $this->baseurl = $upload_dir['baseurl']; $this->basedir = $upload_dir['basedir']; $this->log_path = $this->basedir . DIRECTORY_SEPARATOR . 'local.log'; } public function save($remote_attachment) { $results = array( 'crc' => $remote_attachment['crc'], 'source' => $remote_attachment['url'], 'uri' => str_replace($this->baseurl, '', $remote_attachment['sizes']['full']['url']) ); if (isset($remote_attachment['real_width'])) $results['width'] = $remote_attachment['real_width']; if (isset($remote_attachment['real_height'])) $results['height'] = $remote_attachment['real_height']; if (isset($remote_attachment['watermark'])) $results['watermark'] = 1; if (isset($remote_attachment['cloudStorage'])) $results['cloudStorage'] = $remote_attachment['cloudStorage']; $this->log($results); } public function format($results) { $code = array(); foreach ($results as $key => $value) { $code[] = $key . '::' . $value; } return implode('|', $code); } public function parse($codes) { $results = array(); $codes = trim($codes); $codes = explode('|', $codes); foreach ($codes as $code) { $code = explode('::', $code); $results[$code[0]] = $code[1]; } return $results; } public function log($results) { $crc = $results['crc']; $results = $this->format($results); if (file_exists($this->log_path)) { $log_code = file_get_contents($this->log_path); } else { touch($this->log_path); $log_code = ''; } if (strlen($log_code) > 10) { if (!preg_match('/crc::'.$crc.'/i', $log_code)) { $log_code .= "\n" . $results; } } else { $log_code = $results; } file_put_contents($this->log_path, "\xEF\xBB\xBF" . $log_code); } public function check_is_downloaded($type, $remote_attachment, $point='src') { if (file_exists($this->log_path)) { $log_code = file_get_contents($this->log_path); if (strlen($log_code) > 10) { switch ($point) { case 'src': $source = $this->encode_pattern($remote_attachment['url']); $preg = preg_match('/.*\|source::'.$source.'.*/i', $log_code, $match); if ($preg) { $remote_attachment['downloaded'] = 1; } break; case 'crc': $crc = $this->encode_pattern($remote_attachment['crc']); if (preg_match('/crc::'.$crc.'\|.*/i', $log_code, $match)) { $remote_attachment['downloaded'] = 1; } break; } if ($remote_attachment['downloaded']) { $results = $this->parse($match[0]); switch ($type) { case 'image': $remote_attachment['sizes'] = array( 'full' => array( 'url' => $this->baseurl . $results['uri'], 'width' => $results['width'], 'height' => $results['height'] ) ); $remote_attachment['file_path'] = array( 'full' => $this->basedir . str_replace('/', DIRECTORY_SEPARATOR, $results['uri']) ); break; case 'video': case 'audio': case 'text': case 'application': default: $remote_attachment['file_src'] = $this->baseurl . $results['uri']; $remote_attachment['file_path'] = $this->basedir . str_replace('/', DIRECTORY_SEPARATOR, $results['uri']); break; } } } } return $remote_attachment; } public function refresh_local_cache() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; set_time_limit(36000); $msg = __('The cache is empty.', $this->text_domain); if (file_exists($this->log_path)) { $log_code = file_get_contents($this->log_path); if (strlen($log_code) > 10) { $codes = explode("\n", $log_code); if (!empty($codes)) foreach ($codes as $code) { if ($code) { $results = $this->parse($code); $filepath = $this->basedir . str_replace('/', DIRECTORY_SEPARATOR, $results['uri']); if (!file_exists($filepath)) { $log_code = str_replace($code, '', $log_code); } } } file_put_contents($this->log_path, $log_code); $msg = __('Refreshed local cache has been completed.', $this->text_domain); } } echo $msg; exit; } public function get_local_cache() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; $upload_dir = wp_upload_dir(); $results = array( 'msg' => __('The cache is empty.', $this->text_domain), 'list' => array(), 'upload_url' => $upload_dir['baseurl'] ); if (file_exists($this->log_path)) { $log_code = file_get_contents($this->log_path); if (strlen($log_code) > 10) { $codes = explode("\n", $log_code); if (!empty($codes)) foreach ($codes as $code) { if ($code) { $results['list'][] = $this->parse($code); } } } } print json_encode($results, JSON_INVALID_UTF8_IGNORE); exit; } public function remove_local_cache() { if ( !current_user_can( $this->options->qc_authorization_who_can_use ) ) return; if (!isset($_POST['uri']) || empty($_POST['uri'])) exit; extract($_POST); if (file_exists($this->log_path)) { $log_code = file_get_contents($this->log_path); if (strlen($log_code) > 10) { $codes = explode("\n", $log_code); if (!empty($codes)) foreach ($codes as $code) { if ($code) { $results = $this->parse($code); if ($results['uri'] == $uri) { $filepath = $this->basedir . str_replace('/', DIRECTORY_SEPARATOR, $results['uri']); if (file_exists($filepath)) unlink($filepath); $log_code = str_replace($code, '', $log_code); break; } } } file_put_contents($this->log_path, $log_code); } } print 1; exit; } } ?>